"""Append-only transformation for the sole full-Video owner producer.
This is NOT a replacement producer. Install after the existing selected recipe and
other independent post-deltas. Original immutable task construction stays intact.
"""
BEFORE = '''        val started = environment.download.addTask(task)
        if (started) {
            toast("已开始下载音频")
        } else {
            toast("该任务已在下载中或已完成")
        }
'''
AFTER = '''        // Fixed click publication; never retag this raw audio URL with a later load.
        val expectedDownload = environment.plugins.capturePlaybackDispatch()
        if (expectedDownload == null) {
            toast("无法获取音频地址")
            return
        }
        environment.invocations.launch {
            val stillCaptured = { environment.plugins.isPlaybackDispatchCurrent(expectedDownload) }
            if (!stillCaptured()) return@launch
            val started = environment.download.addTask(task, stillCaptured)
            if (stillCaptured()) {
                if (started) {
                    toast("已开始下载音频")
                } else {
                    toast("该任务已在下载中或已完成")
                }
            }
        }
'''

def captured_audio_download_delta(path, body):
    if path != 'com/android/purebilibili/feature/video/viewmodel/VideoPlaybackViewModel.kt':
        return body
    assert body.count(BEFORE) == 1, 'original synchronous audio addTask/toast anchor'
    return body.replace(BEFORE, AFTER, 1)


