def danmaku_submission_lifetime_delta(path, body):
 if path!='com/android/purebilibili/feature/video/viewmodel/VideoPlaybackViewModel.kt':return body
 importAnchor='import kotlinx.coroutines.launch\n'
 assert body.count(importAnchor)==1
 body=body.replace(importAnchor,importAnchor+'import kotlinx.coroutines.ensureActive\n',1)
 anchor='    private val _isSendingDanmaku = MutableStateFlow(false)\n'
 assert body.count(anchor)==1
 body=body.replace(anchor,anchor+'    @Volatile private var desktopDanmakuSubmissionSerial = 0L\n',1)
 a=body.index('    fun sendDanmaku(\n');z=body.index('    // 弹幕发送成功事件',a)
 before=body[a:z];part=before
 launch='        environment.invocations.launch {\n            _isSendingDanmaku.value = true\n'
 assert part.count(launch)==1
 admission='''        val clickedBvid = current.info.bvid
        val clickedCid = currentCid
        val clickedLoadToken = currentLoadRequestToken
        var submissionId = 0L
        if (!environment.commit {
            submissionId = ++desktopDanmakuSubmissionSerial
            _isSendingDanmaku.value = true
        }) return
        fun releaseSubmission() {
            environment.commit {
                if (desktopDanmakuSubmissionSerial == submissionId) _isSendingDanmaku.value = false
            }
        }
        fun ensureSubmissionSubject() {
            environment.assertCurrent()
            if (currentBvid != clickedBvid || currentCid != clickedCid || currentLoadRequestToken != clickedLoadToken)
                throw kotlinx.coroutines.CancellationException("Danmaku clicked subject retired")
        }
        val submission = try { environment.invocations.launch {
            try {
            kotlinx.coroutines.currentCoroutineContext().ensureActive()
            ensureSubmissionSubject()
'''
 part=part.replace(launch,admission,1)
 assert part.count('                        cid = currentCid,')==2
 part=part.replace('                        cid = currentCid,','                        cid = clickedCid,')
 callback='            result\n                .onSuccess {'
 assert part.count(callback)==1
 part=part.replace(callback,'''            kotlinx.coroutines.currentCoroutineContext().ensureActive()
            ensureSubmissionSubject()
            if (desktopDanmakuSubmissionSerial != submissionId) return@launch
            result
                .onSuccess {''',1)
 tail='            _isSendingDanmaku.value = false\n        }\n    }\n'
 assert part.count(tail)==1
 part=part.replace(tail,'''            } finally { releaseSubmission() }
        } } catch (failure: Throwable) { releaseSubmission(); throw failure }
        // Capture/launch can be cancelled before its original body starts.
        submission.invokeOnCompletion { releaseSubmission() }
    }
''',1)
 return body[:a]+part+body[z:]



